        (N'VIEW_XYZ_AXES_TOGGLE', N'design', N'Visor · Vista', N'Ejes XYZ', N'XYZ axes', NULL, N'click:#ma-stl-xyz-axes-toggle', NULL, NULL, 0, 0, 0, 790),
        (N'VIEW_SIDE_PANEL_COLLAPSE', N'design', N'Visor · Vista', N'Ocultar panel lateral', N'Hide side panel', NULL, N'click:#desing2-stl-side-panel-collapse', NULL, NULL, 0, 0, 0, 800),
        (N'DESIGN_SAVE_VIEW', N'design', N'Visor · Diseño y datos', N'Guardar vista', N'Save view', NULL, N'click:#ma-stl-save-viewer-state', NULL, NULL, 0, 0, 0, 810),
        (N'DESIGN_SCREENSHOT', N'design', N'Visor · Diseño y datos', N'Captura de pantalla', N'Screenshot', NULL, N'click:#ma-stl-screenshot|maStlDownloadDesignScreenshot', NULL, NULL, 0, 0, 0, 820),
        (N'DESIGN_MATERIAL_COUNT', N'design', N'Visor · Diseño y datos', N'Recuento de materiales (diseño)', N'Material count (design)', NULL, N'click:#ma-stl-material-count', NULL, NULL, 0, 0, 0, 830),
        (N'DESIGN_GROUPS', N'design', N'Visor · Diseño y datos', N'Grupos del diseño', N'Design groups', NULL, N'click:#ma-stl-design-groups', NULL, NULL, 0, 0, 0, 840),
        (N'DESIGN_WALL_LIST_FORM', N'design', N'Visor · Diseño y datos', N'Listado masivo de muros', N'Bulk wall list', NULL, N'click:#ma-stl-wall-list', NULL, NULL, 0, 0, 0, 850),
        (N'WALL3D_CONCRETE_MAP', N'design', N'Visor · Diseño y datos', N'Mapeo de hormigón', N'Concrete mapping', NULL, N'click:#desing2-stl-right-panel-wall-map|maStlWall3dToggleConcreteMapping', NULL, NULL, 0, 0, 0, 860),
        (N'CONNECTION_TEST', N'design', N'Visor · Diseño y datos', N'Estado de la conexión', N'Connection status', NULL, N'click:#desing2-stl-right-panel-connection-test', NULL, NULL, 0, 0, 0, 870),
        (N'SIDE_TAB_ENVIRONMENT', N'design', N'Visor · Diseño y datos', N'Pestaña Entorno', N'Environment tab', NULL, N'click:[data-tab=entorno]', NULL, NULL, 0, 0, 0, 880),
        (N'SIDE_TAB_CONFIG', N'design', N'Visor · Diseño y datos', N'Pestaña Configuración', N'Settings tab', NULL, N'click:[data-tab=config]', NULL, NULL, 0, 0, 0, 890),
        (N'DESIGN_LEAVE', N'design', N'Visor · Diseño y datos', N'Salir del diseño', N'Leave design', NULL, N'click:#ma-stl-leave-design', NULL, NULL, 0, 1, 0, 900),
        (N'PLUGIN_UPDATE_LIBRARY', N'design', N'Visor · Plugin CAD', N'Actualizar biblioteca', N'Update library', NULL, N'click:#ma-stl-plugin-update', NULL, NULL, 0, 0, 0, 910),
        (N'PLUGIN_HOME', N'design', N'Visor · Plugin CAD', N'Menú general', N'Main menu', NULL, N'click:#ma-stl-plugin-home', NULL, NULL, 0, 0, 0, 920),
        (N'PLUGIN_BLOCKS', N'design', N'Visor · Plugin CAD', N'Biblioteca de bloques', N'Block library', NULL, N'click:#ma-stl-plugin-blocks', NULL, NULL, 0, 0, 0, 930),
        (N'PLUGIN_CONVERT', N'design', N'Visor · Plugin CAD', N'Cambiar tipo de bloques', N'Change block type', NULL, N'click:#ma-stl-plugin-convert', NULL, NULL, 0, 0, 0, 940),
        (N'PLUGIN_SAVE_WALLS', N'design', N'Visor · Plugin CAD', N'Salvar muros (CAD)', N'Save walls (CAD)', NULL, N'click:#ma-stl-plugin-save', NULL, NULL, 0, 0, 0, 950);

        TextCode, TextContext, TextGroup, TextNameEs, TextNameEn, TextDescription, TextHandler, TextAiCommandId, TextParamsJson,
        Is_Destructive, Is_Confirm, Is_AiImplemented, NumberOrder,
        TextLabel, Is_Delete, Is_Active, LinkMadeBy, LinModifiedBy, AddDateMade, AddLastDateChange, Ntimeschanged
    )
    SELECT S.TextCode, S.TextContext, S.TextGroup, S.TextNameEs, S.TextNameEn, S.TextDescription, S.TextHandler, S.TextAiCommandId, S.TextParamsJson,
           S.Is_Destructive, S.Is_Confirm, S.Is_AiImplemented, S.NumberOrder,
           S.TextNameEs, 0, 1, @User, NULL, GETDATE(), NULL, 0
      FROM @Cmd S
     WHERE NOT EXISTS (SELECT 1 FROM dbo.TSql_AiCommand T WHERE T.TextCode = S.TextCode AND T.Is_Delete = 0);

    DECLARE @Phr TABLE
    (
        TextCode NVARCHAR(60) NOT NULL, TextLanguageCode NVARCHAR(10) NOT NULL, TextPhrase NVARCHAR(200) NOT NULL,
        TextPhraseNorm NVARCHAR(200) NOT NULL, TextKind NVARCHAR(20) NOT NULL, TextConcept NVARCHAR(40) NULL,
        NumberWeight DECIMAL(6,2) NULL, NumberOrder INT NOT NULL
    );


    /* Frases que chocarían con otro comando (mismo contexto + idioma): se informan y no se insertan. */
    SELECT S.TextCode, S.TextLanguageCode, S.TextPhrase, OC.TextCode AS ConflictsWith
      FROM @Phr S
      JOIN dbo.TSql_AiCommand C ON C.TextCode = S.TextCode AND C.Is_Delete = 0
      JOIN dbo.TSql_AiCommandPhrase O ON O.TextContext = C.TextContext AND O.TextLanguageCode = S.TextLanguageCode
                                     AND O.TextPhraseNorm = S.TextPhraseNorm AND O.Is_Delete = 0
                                     AND O.TextKind IN (N'keyword', N'example') AND O.LinkAiCommand <> C.IdObject
      JOIN dbo.TSql_AiCommand OC ON OC.IdObject = O.LinkAiCommand
     WHERE S.TextKind IN (N'keyword', N'example');

        LinkAiCommand, TextContext, TextLanguageCode, TextPhrase, TextPhraseNorm, TextKind, TextConcept, NumberWeight, NumberOrder,
        TextLabel, Is_Delete, Is_Active, LinkMadeBy, LinModifiedBy, AddDateMade, AddLastDateChange, Ntimeschanged
    )
    SELECT C.IdObject, C.TextContext, S.TextLanguageCode, S.TextPhrase, S.TextPhraseNorm, S.TextKind, S.TextConcept, S.NumberWeight, S.NumberOrder,
           S.TextPhrase, 0, 1, @User, NULL, GETDATE(), NULL, 0
      FROM @Phr S
      JOIN dbo.TSql_AiCommand C ON C.TextCode = S.TextCode AND C.Is_Delete = 0
     WHERE NOT EXISTS (SELECT 1 FROM dbo.TSql_AiCommandPhrase T
                        WHERE T.LinkAiCommand = C.IdObject AND T.TextLanguageCode = S.TextLanguageCode
                          AND T.TextPhraseNorm = S.TextPhraseNorm AND T.Is_Delete = 0)
       AND (S.TextKind NOT IN (N'keyword', N'example') OR NOT EXISTS (
               SELECT 1 FROM dbo.TSql_AiCommandPhrase O
                WHERE O.TextContext = C.TextContext AND O.TextLanguageCode = S.TextLanguageCode
                  AND O.TextPhraseNorm = S.TextPhraseNorm AND O.Is_Delete = 0 AND O.TextKind IN (N'keyword', N'example')));

    PRINT N'OK — semilla TSql_AiCommand (95 comandos) y TSql_AiCommandPhrase (989 frases ES/EN).';
END
GO
